export const coverageTemplate=`<section id="coverage" hidden><div class="sectionhead"><div><h2>파티 상성 분석</h2><p>현재 파티의 18타입 방어 배율과 공통 약점을 확인하고, 빈틈을 줄이는 멤버를 비교합니다.</p></div><div class="coverage-actions"><button id="coverageLoad" class="primary">현재 파티 불러오기</button><button id="coverageReset">파티 편집</button></div></div><div id="coverageParty" class="coverage-party"></div><div class="coverage-layout"><div class="sectionhead"><h2>방어 상성</h2><span class="tag" id="coverageMode"></span></div><div id="coverageTable" class="tablewrap"></div><p class="coverage-note">기본 타입 기준입니다. 특성·도구·테라스탈·메가진화 및 실제 내구는 추천 근거에 자동으로 단정해 반영하지 않습니다.</p><section class="coverage-recommendations-block"><div class="sectionhead"><h2>추천 멤버</h2><span class="tag">전후 비교</span></div><p class="asidehint">해결하는 약점과 새로 생기는 약점을 함께 표시합니다.</p><div id="coverageRecommendations"></div></section></div></section>`;

