export const leadTemplate=`<section id="lead" hidden><div class="sectionhead"><div><h2>1분 선출 추천</h2><p>선출 화면을 기기 안에서 먼저 읽습니다. 내·상대 파티를 최종 확인한 뒤 싱글 3마리, 더블 4마리의 순서를 추천합니다.</p></div><span class="tag">빠른 확인 필수</span></div><div class="leadgrid"><div class="uploadpanel"><label class="dropzone"><strong>선출 화면 선택</strong><span>좌측 내 파티 · 우측 상대 파티가 모두 보이는 PNG/JPG/WebP</span><input type="file" id="leadFile" accept="image/png,image/jpeg,image/webp"></label><img id="leadPreview" alt="선출 화면 미리보기" hidden><button id="leadRead" class="primary" disabled>기기에서 다시 인식</button><button id="leadAI" disabled>AI 보조 인식 (이미지 전송)</button><p id="leadStatus" role="status">이미지를 선택하면 로컬 이미지 DB로 후보를 찾습니다. 자동으로 AI에 전송하지 않습니다.</p><details><summary>인식 및 비용 안내</summary><p>기기 내 인식은 외부 AI 호출 비용이 없습니다. 확실하지 않은 칸은 후보를 선택해 확인하세요. AI 보조 인식 버튼을 누르면 축소한 화면을 서버로 보내며 API 비용이 발생할 수 있습니다. 인식 결과는 확정값이 아니며, 잘못된 칸은 검색으로 즉시 교정한 뒤 추천을 실행하세요.</p></details></div><div><div class="leadcolumns"><div><h3>내 파티</h3><div id="leadMine" class="leadslots"></div></div><div><h3>상대 파티</h3><div id="leadOpponent" class="leadslots"></div></div></div><div class="leadactions"><button id="leadRecommend" class="primary" disabled>선출과 순서 추천</button></div><div id="leadResult"></div></div></div></section>`;

export const calculatorTemplate=`<section id="calculators" hidden><div class="sectionhead"><div><h2>챔피언스 계산기</h2><p>공격측과 방어측을 나눠 세팅하고 피해·내구·스피드를 비교합니다.</p></div><span class="tag">86~100 난수</span></div><div class="calc-sides"><section class="calc-side calc-attack"><h3>공격</h3><div class="calc-side-grid"><label>공격 포켓몬<input id="calcAtk" list="calcMons" autocomplete="off"></label><label>기술<select id="calcMove"></select></label><label>공격 EV (H/A/B/C/D/S)<input id="calcAtkEvs" value="0,0,0,0,0,0"></label><label>공격 성격<select id="calcAtkNature"></select></label><label>공격 도구<select id="calcAtkItem"></select></label><label>공격 특성<select id="calcAtkAbility"></select></label><label>공격 랭크<select id="calcAtkRank"><option>0</option><option>+1</option><option>+2</option><option>+3</option><option>+4</option><option>+5</option><option>+6</option><option>-1</option><option>-2</option><option>-3</option><option>-4</option><option>-5</option><option>-6</option></select></label><label>날씨<select id="calcWeather"><option>없음</option><option>쾌청</option><option>비</option><option>모래바람</option><option>눈</option></select></label><label>필드<select id="calcField"><option>없음</option><option>일렉트릭필드</option><option>그래스필드</option><option>사이코필드</option><option>미스트필드</option></select></label><label>테라/메가<select id="calcForm"><option>없음</option><option>테라스탈</option><option>메가진화</option></select></label></div><fieldset class="calc-special"><legend>특수 상황</legend><label><input id="calcCritical" type="checkbox"> 급소</label><label><input id="calcCharge" type="checkbox"> 충전</label><label><input id="calcHelping" type="checkbox"> 도우미</label><label><input id="calcBattery" type="checkbox"> 배터리</label></fieldset></section><section class="calc-side calc-defense"><h3>방어</h3><div class="calc-side-grid"><label>방어 포켓몬<input id="calcDef" list="calcMons" autocomplete="off"></label><label>현재 체력 (%)<input id="calcHpPercent" type="number" min="1" max="100" value="100"></label><label>타수<input id="calcHits" type="number" min="1" max="10" value="1"></label><label>방어 EV (H/A/B/C/D/S)<input id="calcDefEvs" value="0,0,0,0,0,0"></label><label>방어 성격<select id="calcDefNature"></select></label><label>방어 도구<select id="calcDefItem"></select></label><label>방어 특성<select id="calcDefAbility"></select></label><label>방어 랭크<select id="calcDefRank"><option>0</option><option>+1</option><option>+2</option><option>+3</option><option>+4</option><option>+5</option><option>+6</option><option>-1</option><option>-2</option><option>-3</option><option>-4</option><option>-5</option><option>-6</option></select></label><label>벽<select id="calcWall"><option>없음</option><option>리플렉터</option><option>빛의장막</option><option>오로라베일</option></select></label><label>더블 보정<select id="calcDouble"><option>없음</option><option>더블 배틀</option></select></label></div></section></div><p class="leadnotice">랭크·쾌청/비·일렉트릭/그래스필드·벽·급소·충전·도우미·배터리는 계산에 반영합니다. 테라스탈·방어 도구/특성·더블 보정과 그 밖의 날씨/필드는 공식 적용이 완성되지 않아 결과에 제외 항목으로 표시합니다.</p><div class="calcactions"><button id="calcPowerSweep" class="primary">결정력 일괄 계산</button><button id="calcSpeedCompare" class="primary">스피드 티어 비교</button><button id="calcRun">상세 피해·내구 계산</button></div><div id="calcResult" class="calcresult"></div><datalist id="calcMons"></datalist></section><dialog id="imageViewer"><div class="dialoghead"><strong>업로드 이미지</strong><button data-close="imageViewer" aria-label="닫기">×</button></div><img id="imageViewerImg" alt="업로드 이미지 크게 보기"></dialog>`;
